<script setup lang="ts">
import {computed,ref,watch,onBeforeUnmount} from 'vue';
import {onBeforeRouteLeave} from 'vue-router';
import type {AdminClient,ContentDraft,Release,PackageExportReceipt,PublishCheckReport,Operations} from '@loreviva/sdk-ts';
import {useProjectStore} from '../stores/project';
import {useTasksStore} from '../stores/tasks';
import {createCommandRunner} from '../lib/commands';
import FieldErrors from './FieldErrors.vue';
const props=defineProps<{approval?:boolean;releases?:Release[]}>();const s=useProjectStore();const tasks=useTasksStore();const runner=computed(()=>createCommandRunner(s.client));const pending=computed(()=>runner.value.pending.value);const pendingKey=computed(()=>(pending.value?.input as {headers?:Record<string,string>}|undefined)?.headers?.['Idempotency-Key']??'');const busy=ref(false),error=ref<unknown>(),report=ref<PublishCheckReport>(),approved=ref<ContentDraft>(),receipt=ref<PackageExportReceipt>();const rehearsal=ref(''),note=ref(''),attested=ref(false),selected=ref(''),packageId=ref(''),packageVersion=ref('1.0.0'),author=ref('');let epoch=0;let downloadController:AbortController|undefined;
type Scope={client:AdminClient;tenant:string;product:string;bearer:string;epoch:number};function capture():Scope{return {client:s.client,tenant:s.tenantId,product:s.productId,bearer:s.bearer,epoch:++epoch}}function current(c:Scope){return c.epoch===epoch&&c.client===s.client&&c.tenant===s.tenantId&&c.product===s.productId&&c.bearer===s.bearer}
function saved(){s.assertImpactReady();if(!s.basis||s.dirty)throw Error('请先保存或取消本地修改');return s.basis}
async function check(){const c=capture();busy.value=true;try{const d=saved();const r=await runner.value.run('checkDraftForPublish',{path:{draft_id:d.draft_id},headers:{'Idempotency-Key':crypto.randomUUID()},body:{product_id:c.product,expected_draft_revision:d.draft_revision,requested_support_labels:['MOCK_DEMO']}});if(current(c)){report.value=r;error.value=undefined}}catch(e){if(current(c))error.value=e}finally{if(current(c))busy.value=false}}
async function rehearse(){const c=capture();busy.value=true;try{const d=saved();const world=d.input.objects.find(o=>o.object_id===d.input.root_object_id&&o.kind==='WORLD');if(!world||world.kind!=='WORLD')throw Error('此内容不需要世界试演');const id=await tasks.rehearse({product_id:c.product,expected_draft_revision:d.draft_revision,mode:'MOCK',fixture:'COFFEE',inputs:[{actor_slot:world.primary_actor_slot,text:'A bounded local rehearsal.'}],max_cost_units:'0',assertions:['ISOLATED','RIGHTS','DUTIES','SIGN_CUSTODY']});if(current(c)){rehearsal.value=id;error.value=undefined}}catch(e){if(current(c))error.value=e}finally{if(current(c))busy.value=false}}
async function refresh(){try{await tasks.refresh(rehearsal.value);error.value=undefined}catch(e){error.value=e}}
async function applyApproval(result:ContentDraft,c:Scope){if(!current(c))return;approved.value=result;if(!s.dirty&&s.basis?.draft_id===result.draft_id)s.acceptDraft(result);error.value=undefined}
async function approve(){const c=capture();busy.value=true;try{const d=saved();if(!attested.value||!report.value?.passed||report.value.draft_revision!==d.draft_revision)throw Error('请检查当前修订并核对权利');const value=await runner.value.run('approvePackageDraft',{path:{draft_id:d.draft_id},headers:{'Idempotency-Key':crypto.randomUUID()},body:{product_id:c.product,expected_draft_revision:d.draft_revision,check_report_id:report.value.report_id,rights_attested:true,approval_note:note.value,...(d.root_kind==='WORLD'?{rehearsal_task_id:rehearsal.value}:{})}});await applyApproval(value,c)}catch(e){if(current(c))error.value=e}finally{if(current(c))busy.value=false}}
async function exportPackage(){const c=capture();busy.value=true;try{if(!attested.value)throw Error('请先核对分享权利');const value=await runner.value.run('exportContentPackage',{headers:{'Idempotency-Key':crypto.randomUUID()},body:{product_id:c.product,release_id:selected.value,package_id:packageId.value,package_version:packageVersion.value,author_display_name:author.value,rights_attested:true}});if(current(c)){receipt.value=value;error.value=undefined}}catch(e){if(current(c))error.value=e}finally{if(current(c))busy.value=false}}
async function retry(){const p=pending.value;if(!p)return;const c=capture();busy.value=true;try{if(p.operation==='approvePackageDraft'){const value=await runner.value.run(p.operation,p.input as Operations['approvePackageDraft']['input']);await applyApproval(value,c)}else if(p.operation==='exportContentPackage'){const value=await runner.value.run(p.operation,p.input as Operations['exportContentPackage']['input']);if(current(c))receipt.value=value}else if(p.operation==='checkDraftForPublish'){const value=await runner.value.run(p.operation,p.input as Operations['checkDraftForPublish']['input']);if(current(c))report.value=value}else throw Error('请在原操作入口恢复此请求');if(current(c))error.value=undefined}catch(e){if(current(c))error.value=e}finally{if(current(c))busy.value=false}}
async function download(){const value=receipt.value;if(!value)return;const c=capture();busy.value=true;const controller=new AbortController();downloadController=controller;try{const bytes=await c.client.downloadPackage(value,c.product,controller.signal);if(!current(c)||controller.signal.aborted)return;const url=URL.createObjectURL(new Blob([bytes as Uint8Array<ArrayBuffer>],{type:'application/zip'}));try{const a=document.createElement('a');a.href=url;a.download=value.package_id+'-'+value.package_version+'.wepkg';a.click()}finally{URL.revokeObjectURL(url)}error.value=undefined}catch(e){if(current(c))error.value=e}finally{if(current(c))busy.value=false}}
watch(()=>[s.client,s.tenantId,s.productId,s.bearer],()=>{epoch++;downloadController?.abort();busy.value=false;receipt.value=undefined;report.value=undefined;approved.value=undefined;rehearsal.value='';error.value=undefined;attested.value=false});watch(()=>[s.basis?.draft_id,s.basis?.draft_revision],()=>{report.value=undefined;attested.value=false});onBeforeUnmount(()=>{epoch++;downloadController?.abort()});onBeforeRouteLeave(()=>!pending.value||window.confirm('仍有操作结果待核验，请保留原请求标识。确认离开？'));
</script>
<template><section class="panel" :aria-label="approval?'隔离审核':'内容包导出'"><h2>{{approval?'审核隔离内容':'导出静态内容包'}}</h2><FieldErrors :error="error"/>
<template v-if="approval&&s.basis"><p>审核只批准当前保存的修订；编辑、复制或恢复后需要重新审核。发布仍是独立操作。</p><p>当前状态：{{s.basis.state}} · 修订 {{s.basis.draft_revision}}</p><button :disabled="busy||s.dirty||!!pending" @click="check">检查隔离修订</button><p v-if="report">{{report.passed?'发布条件检查通过':'仍有需要处理的条件'}} · 修订 {{report.draft_revision}}</p><FieldErrors v-if="report" :findings="report.findings"/>
<template v-if="s.basis.root_kind==='WORLD'"><button :disabled="busy||s.dirty||!!pending" @click="rehearse">运行完整 Mock 试演</button><label>原试演任务标识<input v-model="rehearsal"></label><button :disabled="!rehearsal||busy" @click="refresh">刷新试演结果</button><p v-if="tasks.views[rehearsal]">试演状态：{{tasks.views[rehearsal].task_state}}</p><p class="muted">服务端会核验原任务、输入、全部适用断言及当前来源；填写标识不代表已经通过。</p></template>
<label>审核说明<textarea v-model="note" maxlength="500"/></label><label><input v-model="attested" type="checkbox">我已核对来源许可、用途和当前修订。</label><button class="primary" :disabled="busy||s.dirty||!attested||!note||!report?.passed||!!pending||s.basis.state!=='ISOLATED_IMPORT'" @click="approve">批准当前隔离修订</button><p v-if="approved" role="status">服务端已审核修订 {{approved.draft_revision}}；原来源记录继续保留。</p><button v-if="approved&&s.dirty" @click="s.acceptDraft(approved)">采用服务器审核修订（放弃本地修改）</button></template>
<template v-else-if="!approval"><p>仅导出有权分享的静态定义和素材。模型只携带能力需求，另一安装需重新映射；不包含玩家、记忆、运行状态或凭据。</p><label>已发布内容<select v-model="selected" :disabled="busy||!!pending"><option value="">请选择</option><option v-for="release in releases??[]" :key="release.release_id" :value="release.release_id">{{release.input.name}} · 修订 {{release.draft_revision}}</option></select></label><label>内容包标识<input v-model="packageId" placeholder="my.world" :disabled="busy||!!pending"></label><label>内容包版本<input v-model="packageVersion" :disabled="busy||!!pending"></label><label>公开作者名<input v-model="author" :disabled="busy||!!pending" maxlength="200"></label><label><input v-model="attested" type="checkbox" :disabled="busy||!!pending">我确认所有纳入内容和素材允许复制与再分发。</label><button class="primary" :disabled="busy||!!pending||!selected||!attested||!packageId||!author" @click="exportPackage">生成内容包</button><section v-if="receipt"><h3>内容包已生成</h3><p>{{receipt.package_id}} · {{receipt.package_version}} · {{receipt.size_bytes}} 字节</p><p class="break">{{receipt.export_id}}</p><button :disabled="busy" @click="download">下载已核验内容包</button></section></template>
<section v-if="pending" aria-live="polite"><h3>原请求结果待确认</h3><p>停止等待或回复无效不代表操作已经撤销。保留原请求标识，使用同一输入恢复。</p><pre>{{pendingKey}}</pre><button :disabled="busy" @click="retry">恢复原内容包操作</button></section></section></template>
